  async function submitAuth(e: FormEvent) {
    e.preventDefault(); setBusy(true); setError('');
    try {
      const res=await fetch('/api/auth/'+authMode,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password,displayName:name})});
      const data=await res.json(); if(!res.ok) throw new Error(data.error||'Something went wrong');
      setUser(data.user); setPassword('');
    } catch(err) { setError(err instanceof Error?err.message:'Unable to connect.'); }
    finally { setBusy(false); }
  }
  async function logout(){ await fetch('/api/auth/logout',{method:'POST'}).catch(()=>{}); setUser(null); setView('Overview'); }
  async function startPayPalCheckout(planId:string){
    setCheckoutPlan(planId);setPremiumError('');
    try{
      const res=await fetch('/api/paypal/create-order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({planId})});
      const data=await res.json();
      if(!res.ok)throw new Error(data.error||'Could not start PayPal checkout.');
      if(!data.approvalUrl)throw new Error('PayPal did not return an approval link.');
      window.location.assign(data.approvalUrl);
    }catch(err){setPremiumError(err instanceof Error?err.message:'Could not start PayPal checkout.');setCheckoutPlan(null);}
  }
