  if(!user) return <main className="auth-shell"><div className="auth-glow glow-one"/><div className="auth-glow glow-two"/><a className="brand auth-brand" href="#"><span className="brand-mark"><Command size={19}/></span>orbit<span>desk</span></a><section className="auth-card"><div className="eyebrow"><Sparkles size={14}/> YOUR BUSINESS, IN ORBIT</div><h1>{authMode==='login'?'Welcome back.':'Make room to grow.'}</h1><p className="muted">{authMode==='login'?'Sign in to pick up where you left off.':'Create your free workspace. No credit card required.'}</p><form onSubmit={submitAuth} className="auth-form">{authMode==='register'&&<label>Your name<input value={name} onChange={e=>setName(e.target.value)} placeholder="Alex Morgan" required minLength={2}/></label>}<label>Email address<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" required autoComplete="email"/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 10 characters" required minLength={10} autoComplete={authMode==='login'?'current-password':'new-password'}/></label>{error&&<div className="error">{error}</div>}<button className="primary-btn full" disabled={busy}>{busy?'Please wait…':authMode==='login'?'Sign in to OrbitDesk':'Create free account'}<span>→</span></button></form><p className="auth-switch">{authMode==='login'?"New to OrbitDesk?":"Already have an account?"} <button onClick={()=>{setAuthMode(authMode==='login'?'register':'login');setError('')}}>{authMode==='login'?'Create an account':'Sign in'}</button></p><div className="auth-foot"><ShieldCheck size={14}/> Your workspace is private and secure</div></section><p className="copyright">© 2026 OrbitDesk · Built for your next big thing</p></main>;
